import React, { useState, useEffect } from 'react';
import { Play, Pause, SkipForward, Search, X } from 'lucide-react';
import Lecteur from './Lecteur';
import './Bibliotheque.css';

function Bibliotheque({ allerVers, utilisateur }) {
  const [achats, setAchats] = useState([]);
  const [chargement, setChargement] = useState(true);
  const [pisteActive, setPisteActive] = useState(null);
  const [playlist, setPlaylist] = useState([]);
  const [pistesAlbum, setPistesAlbum] = useState({});
  const [filtre, setFiltre] = useState('tous');
  const [recherche, setRecherche] = useState('');

  useEffect(() => {
    if (!utilisateur) { allerVers('login'); return; }
    fetch(`/api/achats/mes-achats/${utilisateur.id}`)
      .then(res => res.json())
      .then(data => {
        setAchats(data.achats);
        setChargement(false);
      })
      .catch(() => setChargement(false));
  }, [utilisateur]);

  const achatsFiltres = achats.filter(a => {
    const matchFiltre = filtre === 'tous' || a.type === filtre;
    const matchRecherche = a.titre.toLowerCase().includes(recherche.toLowerCase()) ||
      a.nom_artiste.toLowerCase().includes(recherche.toLowerCase());
    return matchFiltre && matchRecherche;
  });

  const jouerSingle = (achat) => {
    const singles = achatsFiltres.filter(a => a.type === 'single' && a.fichier_url);
    const pl = singles.map(a => ({
      url: a.fichier_url,
      titre: a.titre,
      artiste: a.nom_artiste,
      pochette: a.pochette_url,
      id: a.id
    }));
    setPlaylist(pl);
    setPisteActive({
      url: achat.fichier_url,
      titre: achat.titre,
      artiste: achat.nom_artiste,
      pochette: achat.pochette_url,
      id: achat.id
    });
  };

  const chargerPistesAlbum = async (musiqueId) => {
    if (pistesAlbum[musiqueId]) {
      setPistesAlbum(prev => ({ ...prev, [musiqueId]: null }));
      return;
    }
    const res = await fetch(`/api/musiques/${musiqueId}/pistes`);
    const data = await res.json();
    setPistesAlbum(prev => ({ ...prev, [musiqueId]: data.pistes }));
  };

  const jouerPiste = (piste, toutes) => {
    const pl = toutes.map(p => ({
      url: p.fichier_url,
      titre: p.titre,
      artiste: '',
      pochette: null,
      id: p.id
    }));
    setPlaylist(pl);
    setPisteActive({
      url: piste.fichier_url,
      titre: piste.titre,
      artiste: '',
      pochette: null,
      id: piste.id
    });
  };

  return (
    <div className="biblio-page">
      <header className="header">
        <div className="logo" onClick={() => allerVers('accueil')}>Varim Music</div>
        <nav className="nav">
          <a href="#" onClick={() => allerVers('accueil')}>Accueil</a>
          <a href="#" onClick={() => allerVers('catalogue')}>Catalogue</a>
          <a href="#" className="actif">Ma Bibliothèque</a>
        </nav>
        <div className="auth-buttons">
          <span className="user-prenom">{utilisateur?.prenom}</span>
          <button className="btn-login" onClick={() => {
            localStorage.removeItem('token');
            localStorage.removeItem('utilisateur');
            allerVers('accueil');
          }}>Déconnexion</button>
        </div>
      </header>

      <div className="biblio-contenu">
        <h1 className="biblio-titre">Ma Bibliothèque</h1>

        <div className="biblio-controls">
          <div className="biblio-filtres">
            <button className={`filtre-btn ${filtre === 'tous' ? 'actif' : ''}`} onClick={() => setFiltre('tous')}>Tous</button>
            <button className={`filtre-btn ${filtre === 'single' ? 'actif' : ''}`} onClick={() => setFiltre('single')}>Singles</button>
            <button className={`filtre-btn ${filtre === 'album' ? 'actif' : ''}`} onClick={() => setFiltre('album')}>Albums</button>
          </div>

          <div className="biblio-recherche">
            <Search size={15} color="#a0aec0" />
            <input
              type="text"
              placeholder="Rechercher dans ma bibliothèque..."
              value={recherche}
              onChange={e => setRecherche(e.target.value)}
            />
            {recherche && (
              <button onClick={() => setRecherche('')}>
                <X size={14} />
              </button>
            )}
          </div>
        </div>

        {chargement ? (
          <div className="chargement">Chargement...</div>
        ) : achatsFiltres.length === 0 ? (
          <div className="vide">
            <p>Aucune musique trouvée.</p>
            <button className="btn-catalogue" onClick={() => allerVers('catalogue')}>
              Découvrir le catalogue
            </button>
          </div>
        ) : (
          <div className="biblio-liste">
            {achatsFiltres.map(achat => (
              <div key={achat.id} className="biblio-carte">
                <div className="biblio-pochette">
                  {achat.pochette_url ? (
                    <img src={achat.pochette_url} alt={achat.titre} />
                  ) : (
                    <div className="pochette-defaut">
                      {achat.type === 'album' ? '◉' : '♪'}
                    </div>
                  )}
                </div>

                <div className="biblio-info">
                  <h3>{achat.titre}</h3>
                  <p>{achat.nom_artiste}</p>
                  <p className="biblio-type">{achat.type === 'album' ? 'Album' : 'Single'}</p>
                </div>

                <div className="biblio-actions">
                  {achat.type === 'single' ? (
                    <button
                      className={`btn-jouer ${pisteActive?.id === achat.id ? 'en-lecture' : ''}`}
                      onClick={() => jouerSingle(achat)}
                    >
                      {pisteActive?.id === achat.id ? <Pause size={16} /> : <Play size={16} />}
                      {pisteActive?.id === achat.id ? 'Pause' : 'Écouter'}
                    </button>
                  ) : (
                    <button
                      className="btn-jouer"
                      onClick={() => chargerPistesAlbum(achat.musique_id)}
                    >
                      {pistesAlbum[achat.musique_id] ? 'Masquer' : 'Voir les pistes'}
                    </button>
                  )}
                </div>

                {achat.type === 'album' && pistesAlbum[achat.musique_id] && (
                  <div className="pistes-album">
                    {pistesAlbum[achat.musique_id].map(piste => (
                      <div key={piste.id} className="piste-ligne">
                        <span className="piste-num">#{piste.numero_ordre}</span>
                        <span className="piste-titre">{piste.titre}</span>
                        <button
                          className={`btn-piste ${pisteActive?.id === piste.id ? 'en-lecture' : ''}`}
                          onClick={() => jouerPiste(piste, pistesAlbum[achat.musique_id])}
                        >
                          {pisteActive?.id === piste.id ? <Pause size={14} /> : <Play size={14} />}
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      {pisteActive && (
        <Lecteur
          piste={pisteActive}
          playlist={playlist}
          onPisteChange={setPisteActive}
          onFermer={() => { setPisteActive(null); setPlaylist([]); }}
        />
      )}
    </div>
  );
}

export default Bibliotheque;
